window.CueI18n.dicts["de"]={"meta.title":"Kostenloser Online-Teleprompter mit Sprachverfolgung und Videoaufnahme | CuePrompt","meta.description":"CuePrompt ist ein kostenloser Online-Teleprompter, der deiner Stimme folgt. Schreibe oder importiere ein Skript, lies in deinem Tempo und nimm Videos im Browser auf. Ohne Anmeldung, ohne Wasserzeichen.","nav.skip":"Zum Teleprompter springen","nav.studio":"Studio","nav.how":"So funktioniert's","nav.resources":"Ressourcen","header.badge":"Deine Skripte bleiben in deinem Browser","header.language":"Sprache","header.shortcuts":"Tastenkürzel","intro.eyebrow":"WENIGER AUSWENDIG LERNEN. MEHR DU.","intro.h1":"Kostenloser Online-Teleprompter","intro.h1em":"Natürlich sprechen. Souverän aufnehmen.","intro.p":"Skript einfügen, Start drücken und CuePrompt folgt deiner Stimme – direkt im Browser.","flow.kicker":"EIN ABLAUF, VIER RUHIGE SCHRITTE","flow.title":"Mach den nächsten Schritt offensichtlich.","flow.note":"Starte überall. Deine Arbeit bleibt auf diesem Gerät.","flow.write.title":"Erstellen","flow.write.copy":"Vorlage, Import oder Entwurf","flow.write.cta":"Skript beginnen ↗","flow.read.title":"Üben","flow.read.copy":"Folge deiner Stimme oder deinem Tempo","flow.read.cta":"Leser öffnen ↓","flow.record.title":"Aufnehmen","flow.record.copy":"Rahme deine Aufnahme im Browser ein","flow.record.cta":"Kamera einrichten ↓","flow.publish.title":"Veröffentlichen","flow.publish.copy":"Text, Untertitel und lokaler Export","flow.publish.cta":"Veröffentlichung vorbereiten ↗","studio.title":"Dein Studio","studio.workspace":"PERSÖNLICHER BEREICH","save.saved":"Auf diesem Gerät gespeichert","save.unavailable":"Speicher nicht verfügbar · Entwurf exportieren","script.heading":"DEIN SKRIPT","script.library":"Bibliothek","script.new":"Neues Skript","script.titleAria":"Skripttitel","script.untitled":"Unbenanntes Skript","script.default":"Mein nächstes großes Video","count.words":"{n} Wörter","count.chars":"{n} Zeichen","count.mixed":"{c} Zeichen + {w} Wörter","count.duration":"~{n} Min. Lesezeit","editor.label":"Skript-Editor","editor.hint":"Klicken zum Schreiben oder Einfügen – Änderungen werden auf diesem Gerät gespeichert","editor.placeholder":"Jede große Geschichte beginnt mit ein paar Worten. Füge dein Skript hier ein oder schreibe es…","editor.aria":"Dein Teleprompter-Skript","editor.tip":"Tipp: „## Titel“ legt einen Abschnitt an · [pause] hält an · [slow] verlangsamt","editor.empty":"Deine nächste große Geschichte beginnt hier.\n\nSchreib links ein paar Worte und mach sie zu deinen.","import.button":"Importieren","import.tooltip":".txt, .md, .docx oder .pdf","ai.button":"KI-Texter","templates.title":"Leeres Blatt? Kennen wir.","templates.sub":"Finde deinen Flow mit einer Vorlage.","tpl.youtube":"YouTube-Intro","tpl.pitch":"Produkt-Pitch","tpl.speech":"Kurze Rede","tpl.meeting":"Zoom-Meeting","tpl.course":"Online-Kurs","tpl.podcast":"Podcast-Einstieg","tab.prompt":"Teleprompter","tab.camera":"Kamera & Aufnahme","mode.aria":"Scrollmodus","mode.steady":"Gleichmäßig","mode.follow":"Sprachverfolgung","state.ready":"BEREIT, WENN DU ES BIST","state.playing":"DU SCHAFFST DAS · WEITER","state.paused":"PAUSIERT · FINDE DEINEN RHYTHMUS","state.listening":"HÖRT ZU · SPRICH NATÜRLICH","state.hold":"PAUSE · DURCHATMEN","state.slow":"LANGSAMER ABSCHNITT","state.recording":"REC","preview.spaceHint":"Start / Pause","sections.button":"Abschnitte","sections.empty":"Füge eine Zeile wie „## Intro“ hinzu, um ein Abschnitts-Lesezeichen anzulegen.","sections.start":"Anfang","fs.toggle":"Vollbild","fs.exit":"Vollbild beenden","fs.slower":"Langsamer","fs.faster":"Schneller","fs.play":"Start oder Pause","play.start":"Starten","play.continue":"Weiter","play.pause":"Pausieren","play.listen":"Sprachverfolgung starten","play.stopListen":"Sprachverfolgung pausieren","play.hint":"Tief durchatmen. Du schaffst das.","reset.aria":"Zurück zum Anfang","record.start":"Aufnehmen","record.stop":"Stoppen & ansehen","shortcut.label":"KÜRZEL","settings.speed":"Geschwindigkeit","settings.slow":"Langsam","settings.fast":"Schnell","settings.size":"Textgröße","settings.mirror":"Text spiegeln","follow.language":"Sprache der Spracherkennung","follow.status.idle":"Die Sprachverfolgung scrollt, während du sprichst, und wartet, wenn du pausierst.","follow.status.listening":"Hört zu…","follow.status.waiting":"Wartet auf deine Stimme…","follow.status.heard":"Gehört: „{text}“","follow.unsupported":"Die Sprachverfolgung braucht Chrome, Edge oder Safari. Dieser Browser hat keine Spracherkennung – der gleichmäßige Modus funktioniert weiterhin.","follow.network":"Der Sprachdienst ist nicht erreichbar. Die Sprachverfolgung nutzt die Online-Spracherkennung des Browsers, die in diesem Netzwerk blockiert sein kann. Auf gleichmäßig umgeschaltet.","follow.denied":"Der Mikrofonzugriff wurde blockiert. Erlaube das Mikrofon, um die Sprachverfolgung zu nutzen.","follow.langUnsupported":"Dein Browser unterstützt diese Sprache nicht. Wähle eine andere.","follow.error":"Die Sprachverfolgung wurde unerwartet beendet. Versuch es noch einmal.","follow.privacy":"Datenschutz: Die Sprachverfolgung sendet dein Mikrofon-Audio zur Transkription an den Sprachdienst deines Browsers (z. B. Google in Chrome, Microsoft in Edge, Apple in Safari). Dein Skript und deine Aufnahmen werden nicht hochgeladen.","options.summary":"Leseeinstellungen","options.sub":"Farben, Layout & Spiegelung","options.textColor":"Textfarbe","options.bg":"Hintergrund","options.width":"Lesebreite","width.wide":"Breit","width.comfortable":"Angenehm","width.narrow":"Schmal","options.spacing":"Zeilenabstand","spacing.normal":"Normal","spacing.relaxed":"Locker","spacing.spacious":"Weit","options.vmirror":"Vertikal spiegeln","options.guide":"Lesehilfe","options.highlight":"Aktuelle Zeile hervorheben","rec.summary":"Kamera & Aufnahme","rec.sub":"Geräte, Qualität & Countdown","rec.camera":"Kamera","rec.mic":"Mikrofon","rec.default":"Standard","rec.resolution":"Auflösung","rec.auto":"Automatisch","rec.format":"Format","rec.countdown":"3-2-1-Countdown","rec.mirrorPreview":"Kameravorschau spiegeln","footer.privacy":"Privat by Design. Skripte und Aufnahmen bleiben in deinem Browser.","footer.free":"Keine Anmeldung. Kein Wasserzeichen. Nur du.","trust.label":"GEMACHT FÜR DEIN NÄCHSTES","trust.youtube":"YouTube-Video","trust.course":"Online-Kurs","trust.demo":"Produktdemo","trust.social":"Social-Story","trust.presentation":"Große Präsentation","how.eyebrow":"VOM SKRIPT INS RAMPENLICHT","how.h2":"Schluss mit „noch ein Take“.","how.p":"Alles, was du brauchst, um wie du selbst zu klingen. Nichts, was stört.","how.s1t":"Finde deine Worte","how.s1p":"Schreibe, füge ein oder importiere eine .txt-, .md-, .docx- oder .pdf-Datei. Jedes Skript wird in deiner Bibliothek auf diesem Gerät gespeichert.","how.s2t":"Finde deinen Rhythmus","how.s2p":"Lass die Sprachverfolgung mit deiner Stimme scrollen oder wähle ein gleichmäßiges Tempo. Füge ##-Abschnitte sowie [pause]- und [slow]-Hinweise hinzu.","how.s3t":"Dein Moment","how.s3p":"Countdown, mit der Kamera aufnehmen, den Take ansehen und herunterladen oder neu aufnehmen.","res.eyebrow":"EIN BISSCHEN HILFE, VIEL SELBSTVERTRAUEN","res.h2":"Gemacht für deine Art zu gestalten.","res.youtube":"Teleprompter für YouTube","res.presentations":"Teleprompter für Präsentationen","res.camera":"Teleprompter mit Kamera","faq.eyebrow":"GUT ZU WISSEN","faq.h2":"Ein paar Fragen, die du vielleicht hast.","faq.q1":"Ist CuePrompt wirklich kostenlos?","faq.a1":"Ja. Editor, Sprachverfolgung, gleichmäßiges Scrollen, Spiegelmodi, Vollbild, Skriptbibliothek und Browser-Aufnahme sind kostenlos – ohne Zeitlimit und ohne Konto. Der KI-Texter ist optional und nutzt deinen eigenen API-Schlüssel.","faq.q2":"Sind meine Skripte privat?","faq.a2":"Deine Skripte werden in diesem Browser gespeichert und Aufnahmen auf deinem Gerät erstellt; CuePrompt hat keinen Server, der sie empfängt. Zwei Ausnahmen, die du steuerst: Die Sprachverfolgung sendet Mikrofon-Audio an den Sprachdienst des Browsers, und der KI-Texter sendet den gewählten Text an den Anbieter, den du einrichtest. Beim Löschen der Browserdaten verschwindet deine Bibliothek – exportiere also ab und zu ein Backup.","faq.q3":"Wie funktioniert die Sprachverfolgung?","faq.a3":"Sie nutzt die eingebaute Spracherkennung des Browsers und scrollt zu den Worten, die du gerade gesagt hast. Übersprungene Wörter und Improvisation sind kein Problem, und sie wartet, wenn du aufhörst zu sprechen. Chrome, Edge und Safari senden das Audio an ihren eigenen Online-Dienst (Google, Microsoft oder Apple); du brauchst also eine Verbindung, die diesen Dienst erreicht. Firefox unterstützt das noch nicht; der gleichmäßige Modus funktioniert überall.","faq.q4":"Kann ich es auf dem Handy nutzen?","faq.a4":"Ja. CuePrompt läuft in Browsern auf Handy, Tablet und Computer, auch im Vollbild mit Bildschirmsteuerung. Kameraaufnahmen brauchen HTTPS sowie Kamera- und Mikrofonfreigabe; die Unterstützung hängt vom Browser ab.","faq.q5":"Wie nehme ich mein Video auf und lade es herunter?","faq.a5":"Wähle Kamera & Aufnahme, erlaube den Zugriff und drücke Aufnehmen. Nach einem 3-2-1-Countdown startet das Skript. Drücke Stoppen, um den Take anzusehen, und lade ihn herunter (MP4 oder WebM, je nach Browser) oder nimm neu auf. Das Skript wird nicht ins Video eingeblendet.","faq.q6":"Kann ich es mit einem echten Teleprompter nutzen?","faq.a6":"Ja. Aktiviere „Text spiegeln“ für Strahlteiler-Glas oder „Vertikal spiegeln“ für Halterungen, die das Bild umdrehen, und wechsle ins Vollbild.","faq.q7":"Wie funktioniert der KI-Texter?","faq.a7":"Füge einen API-Schlüssel eines beliebigen OpenAI-kompatiblen Dienstes ein und gib dessen Basis-URL an. Der Schlüssel wird nur in diesem Browser gespeichert, und Anfragen gehen direkt von deinem Browser an den Anbieter. CuePrompt sieht, speichert oder liefert nie einen Schlüssel.","footer.tagline":"Ein bisschen mehr Selbstvertrauen, Wort für Wort.","footer.download":"Skript herunterladen","help.title":"Finde deinen Flow.","help.play":"Start oder Pause","help.speed":"Geschwindigkeit anpassen","help.reset":"Zurück zum Anfang","help.fullscreen":"Vollbild","help.mode":"Gleichmäßig / Sprachverfolgung wechseln","help.note":"Tastenkürzel funktionieren außerhalb des Editors.","common.close":"Schließen","toast.addScript":"Füge dein Skript hinzu, um zu starten.","toast.wrap":"Geschafft! Zurück zum Anfang, um es noch einmal zu lesen.","toast.template":"Deine Vorlage ist bereit. Mach sie zu deiner.","toast.fileTooBig":"Wähle eine Datei kleiner als {n} MB.","toast.importFail":"Diese Datei konnte nicht gelesen werden. Versuch eine andere.","toast.imported":"„{name}“ als neues Skript importiert.","toast.unsupportedFile":"Dateityp nicht unterstützt. Verwende .txt, .md, .docx oder .pdf.","toast.importing":"Datei wird gelesen…","toast.pdfEmpty":"In diesem PDF wurde kein markierbarer Text gefunden. Gescannte PDFs brauchen zuerst OCR.","toast.fsUnavailable":"Vollbild ist in diesem Browser nicht verfügbar.","toast.camUnsupported":"Kameraaufnahmen brauchen einen unterstützten Browser über HTTPS oder localhost.","toast.camFail":"Kein Zugriff auf Kamera oder Mikrofon.","toast.camReady":"Kamera bereit. Dein Video bleibt auf diesem Gerät.","toast.stopFirst":"Beende zuerst die Aufnahme, bevor du den Modus wechselst.","toast.recFail":"Aufnahme fehlgeschlagen. Bitte erneut versuchen.","toast.recUnavailable":"Aufnahme ist in diesem Browser nicht verfügbar. Versuch Chrome oder Edge.","toast.downloaded":"Aufnahme heruntergeladen. Deine Worte, dein Moment.","cam.allow":"Erlaube Kamera und Mikrofon, um dein Bild in der Vorschau zu sehen.","cam.unavailable":"Kamera nicht verfügbar. Prüfe die Browserberechtigungen und versuch es erneut.","review.title":"Take ansehen","review.download":"Herunterladen","review.retake":"Neu aufnehmen","review.discard":"Verwerfen","review.confirmDiscard":"Diesen Take verwerfen? Er wurde noch nicht heruntergeladen.","lib.title":"Skriptbibliothek","lib.search":"Skripte suchen","lib.new":"Neues Skript","lib.open":"Öffnen","lib.rename":"Umbenennen","lib.duplicate":"Duplizieren","lib.delete":"Löschen","lib.confirmDelete":"„{name}“ löschen? Das kann nicht rückgängig gemacht werden.","lib.copy":"{name} (Kopie)","lib.empty":"Keine Skripte passen zu deiner Suche.","lib.current":"Geöffnet","lib.updated":"Bearbeitet {date}","lib.export":"Backup exportieren","lib.import":"Backup importieren","lib.note":"Skripte werden nur in diesem Browser gespeichert. Exportiere ein Backup, um eine Kopie zu behalten oder sie auf ein anderes Gerät zu übertragen.","lib.imported":"{n} Skripte importiert.","lib.badBackup":"Diese Datei ist kein CuePrompt-Backup.","ai.title":"KI-Texter","ai.badge":"Eigener Schlüssel","ai.intro":"Funktioniert mit jeder OpenAI-kompatiblen API und deinem eigenen Schlüssel. Anfragen gehen direkt von deinem Browser an den Anbieter, und der Schlüssel wird nur in diesem Browser gespeichert. CuePrompt enthält oder empfängt keinen Schlüssel.","ai.settings":"Verbindung","ai.baseUrl":"Basis-URL","ai.model":"Modell","ai.key":"API-Schlüssel","ai.keyHint":"Nur im lokalen Speicher dieses Browsers gespeichert. Verwende einen Schlüssel mit Ausgabenlimit.","ai.forget":"Schlüssel löschen","ai.tabGenerate":"Erstellen","ai.tabRewrite":"Umschreiben","ai.tabTranslate":"Übersetzen","ai.topic":"Thema","ai.topicPh":"z. B. Launch unserer neuen Notiz-App","ai.duration":"Länge (Minuten)","ai.tone":"Tonfall","tone.friendly":"Freundlich","tone.professional":"Professionell","tone.energetic":"Energiegeladen","tone.calm":"Ruhig","ai.outLang":"Sprache des Skripts","ai.rewriteMode":"Umschreiben","rw.shorter":"Kürzer machen","rw.conversational":"Lockerer formulieren","rw.clearer":"Klarer formulieren","rw.custom":"Eigene Anweisung","ai.instruction":"Anweisung","ai.target":"Übersetzen nach","ai.run":"Schreiben","ai.running":"Schreibt…","ai.result":"Ergebnis – vor der Verwendung bearbeiten","ai.replace":"Skript ersetzen","ai.newScript":"Als neues Skript speichern","ai.needKey":"Trage zuerst Basis-URL, Modell und API-Schlüssel unter Verbindung ein.","ai.needTopic":"Beschreibe zuerst ein Thema.","ai.needScript":"Dein Skript ist leer.","ai.errorCors":"Die Anfrage ist nicht durchgegangen. Prüfe die Basis-URL und deine Verbindung – manche Anbieter blockieren auch Anfragen aus dem Browser (CORS).","ai.errorHttp":"Der Anbieter hat einen Fehler gemeldet: {msg}","ai.empty":"Der Anbieter hat eine leere Antwort geliefert.","ai.provider":"Anbieter","ai.pDashscope":"Alibaba Qwen (DashScope, Festland-China)","ai.pDashscopeIntl":"Alibaba Qwen (DashScope, international)","ai.pCustom":"Andere OpenAI-kompatible API","ai.corsNote":"Einen Schlüssel bekommst du in der Konsole von Alibaba Cloud Model Studio (DashScope). DashScope akzeptiert Anfragen direkt aus dem Browser; andere Anbieter blockieren sie eventuell (CORS) und bräuchten einen kleinen Proxy.","compat.badge":"DESKTOP · MOBIL · OHNE INSTALLATION","compat.title":"Funktioniert auf Desktop und Smartphone","compat.copy":"CuePrompt im Browser öffnen und direkt loslegen. Kein App-Download und kein Konto erforderlich.","pip.button":"Schwebender Reader","pip.unsupported":"Der schwebende Reader benötigt Chrome oder Edge auf dem Desktop über HTTPS."};
